/* FAQPage structured data for /platform/support/faqs. Generated by scripts/build-faq-schema.py; do not edit by hand. */
(() => {
  const PATH = "/platform/support/faqs";
  const ID = "graphify-faq-schema";
  const SCHEMA = {"@context": "https://schema.org", "@type": "FAQPage", "@id": "https://docs.graphify.com/platform/support/faqs#faq", "mainEntity": [{"@type": "Question", "name": "What is the difference between Graphify and Graphify CLI?", "acceptedAnswer": {"@type": "Answer", "text": "Graphify is hosted: it indexes your GitHub or GitLab repositories, rebuilds on each push to the default branch, reviews pull requests, and serves every repository through one MCP connection. Open-source Graphify is the free graphifyy package. It builds a graph on your machine, with no account. See Move from Graphify CLI to switch."}}, {"@type": "Question", "name": "Which code hosts does Graphify support?", "acceptedAnswer": {"@type": "Answer", "text": "GitHub and GitLab. Connect them from Repositories. GitHub Enterprise is part of Enterprise. A project that is only on your machine needs open-source Graphify."}}, {"@type": "Question", "name": "Do I need a card to start?", "acceptedAnswer": {"@type": "Answer", "text": "No. The Free plan needs no card. See Plans and pricing for trials and what each plan includes."}}, {"@type": "Question", "name": "Which branch does Graphify index?", "acceptedAnswer": {"@type": "Answer", "text": "The default branch. A push to another branch, or a pull request, does not change the repository graph. Pull requests get their own review against that graph."}}, {"@type": "Question", "name": "How does Graphify compare to codebase-memory-mcp?", "acceptedAnswer": {"@type": "Answer", "text": "A comparison of Graphify and codebase-memory-mcp is on the Graphify vs codebase-memory-mcp page."}}, {"@type": "Question", "name": "Graphify shows no graph for my repository", "acceptedAnswer": {"@type": "Answer", "text": "Open Repositories and read the status. See Repositories and builds."}}, {"@type": "Question", "name": "A build failed. How do I retry it?", "acceptedAnswer": {"@type": "Answer", "text": "Open Builds, filter to the repository, and choose Retry on the latest failed build. On Repositories, a failed repository's Options also offer Retry indexing. Both index the current head of the default branch, not the commit that failed."}}, {"@type": "Question", "name": "An answer misses code I can see locally", "acceptedAnswer": {"@type": "Answer", "text": "Graphify indexes the default branch. Push the code there and wait for Indexed. Uncommitted work and other branches are not in the graph."}}, {"@type": "Question", "name": "I hit a plan limit. What does the message mean?", "acceptedAnswer": {"@type": "Answer", "text": "A limit message does not mean the repository is empty. Compare plans on Plans and pricing."}}, {"@type": "Question", "name": "My agent gets a 429 rate_limited error", "acceptedAnswer": {"@type": "Answer", "text": "It sent too many Ask, query, or MCP requests in a short time. Wait a few seconds and retry with exponential backoff. See Rate limits and plan limits."}}, {"@type": "Question", "name": "Claude says it couldn't retrieve a result. Is that a plan limit?", "acceptedAnswer": {"@type": "Answer", "text": "Sometimes. Claude can hide Graphify's error text, so the message doesn't say why. A request rate limit applies on every plan. A Free plan limit, such as graph size or the repository allowance, shows as a message in Graphify. See Claude shows a generic error to tell them apart."}}, {"@type": "Question", "name": "Does buying more Teams seats raise every limit?", "acceptedAnswer": {"@type": "Answer", "text": "No. Workspace allowances are shared across the workspace and do not multiply by seat count. Talk to Graphify before planning a larger rollout."}}, {"@type": "Question", "name": "When does Graphify review a pull request?", "acceptedAnswer": {"@type": "Answer", "text": "When it is opened, reopened, or marked ready for review. Pushing new commits does not start a review by itself. A repository owner, member, or collaborator comments @graphify review on the pull request to run one. Each review analyzes the full pull request, from where it branched to its latest commit. See Pull request reviews."}}, {"@type": "Question", "name": "How is the merge confidence score worked out?", "acceptedAnswer": {"@type": "Answer", "text": "Each completed review scores the pull request from 1 to 5 using confirmed findings only. A P0 or P1 bug gives 1/5 or 2/5, Fix before merging. A P2 bug or a bug with no priority gives 3/5, Review before merging. A single P2 bug with limited reach gives 4/5 but still says Review before merging. Only P3 bugs or cleanup suggestions give 4/5, and nothing found gives 5/5, both Looks safe to merge. Possible issues the review couldn't confirm never change the score, but a review with any of them says Nothing blocking · N possible issues to check instead of Looks safe to merge. A review that stopped early is scored on what it found. See Merge confidence score."}}, {"@type": "Question", "name": "How do I tell Graphify a finding is wrong?", "acceptedAnswer": {"@type": "Answer", "text": "Reply on the pull request with @graphify wrong , @graphify good , or @graphify suppress . That feedback tunes later reviews. See Learning."}}, {"@type": "Question", "name": "How do I connect my coding assistant?", "acceptedAnswer": {"@type": "Answer", "text": "Add the hosted MCP server, https://api.graphify.com/mcp, and sign in with OAuth in the browser. Each integration page has the exact steps; start at Hosted MCP."}}, {"@type": "Question", "name": "My assistant still uses local tools like get_node", "acceptedAnswer": {"@type": "Answer", "text": "A local graphify entry is still active and wins over the hosted one. Remove it, then restart the assistant. See Move from Graphify CLI."}}, {"@type": "Question", "name": "How does a CI agent sign in without a browser?", "acceptedAnswer": {"@type": "Answer", "text": "Use an API token from the MCP tab of Connectors. Store it as a CI secret, never in the repository."}}, {"@type": "Question", "name": "A tool call fails and lists repositories", "acceptedAnswer": {"@type": "Answer", "text": "The workspace has more than one repository, so the call needs repository_id. Pass one of the names in the error, such as your-org/your-repo, or run list_repositories."}}, {"@type": "Question", "name": "Is Graphify safe to use?", "acceptedAnswer": {"@type": "Answer", "text": "Graphify does not train models on your code. Hosted Graphify encrypts data in transit and at rest and only reads the workspace and repositories you choose. Graphify CLI parses code locally with tree-sitter and needs no LLM for code; add --code-only to skip LLM calls entirely. See Security and data handling."}}, {"@type": "Question", "name": "Does Graphify train models on my code?", "acceptedAnswer": {"@type": "Answer", "text": "No. Code goes to Graphify's LLM subprocessors only to produce results, under terms that prohibit training. See Security and data handling."}}, {"@type": "Question", "name": "How do I delete my data?", "acceptedAnswer": {"@type": "Answer", "text": "Contact the Graphify team to request deletion or export. Content is kept until you delete it or close your account. It is then deleted, usually within a few days and always within 30 days, and gone from backups within 7 days after that. See Security."}}, {"@type": "Question", "name": "Can I run Graphify on my own infrastructure?", "acceptedAnswer": {"@type": "Answer", "text": "Yes, with Enterprise, which is self-hosted and in early access. Open-source Graphify also runs entirely on your machine."}}]};
  const sync = () => {
    const existing = document.getElementById(ID);
    const onPage = window.location.pathname.replace(/\/$/, "") === PATH;
    if (onPage && !existing) {
      const tag = document.createElement("script");
      tag.type = "application/ld+json";
      tag.id = ID;
      tag.textContent = JSON.stringify(SCHEMA);
      document.head.appendChild(tag);
    } else if (!onPage && existing) {
      existing.remove();
    }
  };
  sync();
  let last = window.location.pathname;
  setInterval(() => {
    if (window.location.pathname !== last) { last = window.location.pathname; sync(); }
  }, 500);
})();
